function IGUIWindow:ctor(name_or_root, ...)
    IGUIBase.ctor(self)
    if type(name_or_root) == "string" then
        self.root = GUIManager:loadWindowFromFile(name_or_root, true)
        if not self.root then
            LogUtil.logScriptException(string.format("IGUIWindow:ctor() Can't find window json [%s]", name_or_root))
            return
        end
        self.__name = name_or_root
    else
        self.root = name_or_root
    end
    self:setRoot(self.root)
    self.windowId = GUIManager:applyWindowId()
    renameComponents(self.root, self.windowId)
    self.__name = name_or_root
    self:onLoad(...)
end

