---@return CGUIWindow
function IGUIWindow:getChildWindow(index, type, parent)
    parent = parent or self.root
    if not parent then
        return nil
    end
    return DynamicCast.dynamicCastWindow(type, parent:GetChildByIndex(index))
end

---@return CGUIWindow
function IGUIWindow:getChildWindowByName(name, type)
    name = name .. "-" .. self.windowId
    return GUIManager:getWindowByName(name, type)
end

function IGUIWindow:setVisible(visible)
    if not self.root then
        return
    end
    self.root:SetVisible(visible)
end

return IGUIWindow